package org.example.board.post;

import java.net.URI;

import jakarta.validation.Valid;
import org.example.board.auth.LoginUser;
import org.example.board.common.ApiResponse;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class PostController {

    private final PostService postService;

    public PostController(PostService postService) {
        this.postService = postService;
    }

    @PostMapping("/api/v1/posts")
    public ResponseEntity<ApiResponse<PostDetailResponse>> create(@LoginUser Long userId,
                                                            @Valid @RequestBody PostCreateRequest request) {
        PostDetailResponse created = postService.create(userId, request);
        return ResponseEntity.created(URI.create("/api/v1/posts/" + created.id()))
                .body(ApiResponse.created(created));
    }

    @GetMapping("/api/v1/posts/{postId}")
    public ApiResponse<PostDetailResponse> detail(@PathVariable Long postId,
                                                  @LoginUser(required = false) Long userId) {
        return ApiResponse.ok(postService.detail(postId, userId));
    }
}

